package com.eastoftown.pos; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/billing") public class BillingController {final BillingService billing;final AuthService auth;public BillingController(BillingService b,AuthService a){billing=b;auth=a;}@PostMapping("/checkout") public Object checkout(@Valid @RequestBody BillingService.Checkout i){return billing.checkout(i,auth.current().id());}@GetMapping("/invoices") public Object history(){auth.current();return billing.history();}@GetMapping("/invoices/{id}") public Object invoice(@PathVariable String id){auth.current();return billing.invoice(id);}}
